import java.time.LocalDate
import scala.collection.immutable.TreeMap

final case class SalaryHistory(byStart: TreeMap[LocalDate, Money]) {
  def salaryAt(when: LocalDate): Option[Money] =
    byStart.rangeTo(when).lastOption.map(_._2)         // inclusive upper bound
  def salary(today: LocalDate): Money =
    salaryAt(today).getOrElse(sys.error(s"no salary effective on $today"))

  def setSalary(from: LocalDate, amount: Money): SalaryHistory =
    copy(byStart = byStart.updated(from, amount))
}
